        platform: v.platform,
        keywords: list(v.keywords),
        seeds: list(v.seeds),
        handles: list(v.handles),
        minFollowers: num2(v["min-followers"]),
        maxFollowers: num2(v["max-followers"]),
        budget: Number(v.budget),
        batch: v.batch,
